-- Private provider tests and secret-reveal admissions, separate from settings state.
CREATE TABLE provider_setting_operations(owner_id text NOT NULL REFERENCES users(id),request_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('model-test','mail-test','model-icon','xueqiu-cookie')),request_hash text NOT NULL,config_revision bigint NOT NULL,config_fingerprint text NOT NULL,service_id text,model text,result jsonb,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(owner_id,request_id));
CREATE FUNCTION retain_provider_setting_operation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' OR (to_jsonb(NEW)-'result') IS DISTINCT FROM (to_jsonb(OLD)-'result') OR OLD.result IS NOT NULL THEN RAISE EXCEPTION 'provider settings receipt retained' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER retain_provider_setting_operation BEFORE UPDATE OR DELETE ON provider_setting_operations FOR EACH ROW EXECUTE FUNCTION retain_provider_setting_operation();
CREATE TABLE provider_setting_pages(owner_id text NOT NULL,id uuid NOT NULL,request_id uuid NOT NULL,raw bytea NOT NULL CHECK(octet_length(raw)<=262144),raw_sha256 text NOT NULL,http_status integer,complete boolean NOT NULL,received_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(owner_id,id),UNIQUE(owner_id,request_id),FOREIGN KEY(owner_id,request_id) REFERENCES provider_setting_operations(owner_id,request_id));
CREATE TRIGGER retain_provider_setting_page BEFORE UPDATE OR DELETE ON provider_setting_pages FOR EACH ROW EXECUTE FUNCTION immutable_trade_ledger();
